insert into public.ls_task_definitions values('python-first-function-task',1,'python-first-function',1,'Explain your completed-habit counter','Implement the existing count_completed exercise, then explain a boundary case in your own words.','["Show an empty input and a mixed list of true/false values with expected counts.","Explain why false values do not increase the count.","Describe your check results and confirm the input is unchanged."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('python-list-filters',1,'[{"id":"python-list-filters-q1","prompt":"Which values remain from [4, 2, 4] with minimum 4?","options":[{"id":"a","text":"[4, 4]"},{"id":"b","text":"[4]"},{"id":"c","text":"[]"}],"correctOptionId":"a","explanation":"Both occurrences meet the inclusive boundary; filtering preserves duplicates."},{"id":"python-list-filters-q2","prompt":"Where should the final return go?","options":[{"id":"a","text":"Inside the first matching branch"},{"id":"b","text":"After the loop"},{"id":"c","text":"Before creating the result"}],"correctOptionId":"b","explanation":"Returning after the loop lets every item contribute."},{"id":"python-list-filters-q3","prompt":"What is the result for []?","options":[{"id":"a","text":"None"},{"id":"b","text":"[0]"},{"id":"c","text":"[]"}],"correctOptionId":"c","explanation":"No items are appended, so the new result list stays empty."},{"id":"python-list-filters-q4","prompt":"Why avoid converting the result to a set?","options":[{"id":"a","text":"A set increases every value"},{"id":"b","text":"It removes repeated observations"},{"id":"c","text":"A set cannot hold integers"}],"correctOptionId":"b","explanation":"This contract preserves repeated values and their original order."}]'::jsonb);
insert into public.ls_python_exercise_versions values('python-keep-at-least',1,'["case-1","case-2","case-3","case-4","case-5","case-6"]'::jsonb);
insert into public.ls_course_modules values('python-list-filters','python',1,2,null,'python-keep-at-least',1);
insert into public.ls_task_definitions values('python-list-filters-task',1,'python-list-filters',1,'Filter a study-session list','Implement the filter, then describe one boundary case and the change that made your solution work. Add an HTTPS code link only if you want to.','["Show an example containing an exact-boundary match and a repeated value.","Explain why the output order and input list remain unchanged.","Summarize your check results; a quiz score alone is not the task result."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('python-dictionary-summary',1,'[{"id":"python-dictionary-summary-q1","prompt":"What does iterating over scores directly visit?","options":[{"id":"a","text":"Its keys"},{"id":"b","text":"Only its integers"},{"id":"c","text":"Pairs automatically"}],"correctOptionId":"a","explanation":"Dictionary iteration visits keys; values() explicitly provides values."},{"id":"python-dictionary-summary-q2","prompt":"What summarizes {\"Ari\": 0}?","options":[{"id":"a","text":"{\"count\": 0, \"total\": 0}"},{"id":"b","text":"{\"count\": 1, \"total\": 0}"},{"id":"c","text":"{\"count\": 1, \"total\": 1}"}],"correctOptionId":"b","explanation":"The zero score still belongs to one entry."},{"id":"python-dictionary-summary-q3","prompt":"Which operation counts entries?","options":[{"id":"a","text":"sum(scores.values())"},{"id":"b","text":"scores.clear()"},{"id":"c","text":"len(scores)"}],"correctOptionId":"c","explanation":"len counts dictionary entries, independent of their values."},{"id":"python-dictionary-summary-q4","prompt":"What must the empty case return?","options":[{"id":"a","text":"None"},{"id":"b","text":"{\"count\": 0, \"total\": 0}"},{"id":"c","text":"{}"}],"correctOptionId":"b","explanation":"A fixed result shape makes the empty case usable without special guessing."}]'::jsonb);
insert into public.ls_python_exercise_versions values('python-summarize-scores',1,'["case-1","case-2","case-3","case-4","case-5","case-6"]'::jsonb);
insert into public.ls_course_modules values('python-dictionary-summary','python',1,3,null,'python-summarize-scores',1);
insert into public.ls_task_definitions values('python-dictionary-summary-task',1,'python-dictionary-summary',1,'Explain a score summary','Build the summary function and explain why zero scores and missing entries are different.','["Include an empty dictionary and a dictionary containing a zero score.","Show the exact count/total result shape.","Confirm the input remains unchanged and describe one debugging insight."]'::jsonb);
insert into public.ls_course_modules values('ai-clear-requests','how-to-use-ai',1,1,null,null,null);
insert into public.ls_task_definitions values('ai-clear-requests-task',1,'ai-clear-requests',1,'Improve one unclear request','Write a vague request, improve it with context and constraints, and explain how you would judge the response. Use fictional information.','["Include the original and revised request.","Name the intended audience, desired result, and at least one constraint.","Explain two concrete checks for a useful answer; using an AI account is optional."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('ai-verify-answers',1,'[{"id":"ai-verify-answers-q1","prompt":"A source says the room is not announced. What should the revised answer say?","options":[{"id":"a","text":"Room 4, because it sounds likely"},{"id":"b","text":"The room is not announced"},{"id":"c","text":"Delete the date too"}],"correctOptionId":"b","explanation":"Preserve the known facts and identify the room as unknown."},{"id":"ai-verify-answers-q2","prompt":"Does a citation-shaped URL prove a claim?","options":[{"id":"a","text":"No; inspect the page and its support"},{"id":"b","text":"Yes, if it starts with HTTPS"},{"id":"c","text":"Yes, if the model sounds certain"}],"correctOptionId":"a","explanation":"A real URL can still be irrelevant or fail to support the specific claim."},{"id":"ai-verify-answers-q3","prompt":"The source omits capacity. Which verdict is justified?","options":[{"id":"a","text":"Capacity is definitely zero"},{"id":"b","text":"Capacity is unsupported by this source"},{"id":"c","text":"Capacity must be 30"}],"correctOptionId":"b","explanation":"Missing evidence does not justify inventing a value or declaring a particular alternative true."},{"id":"ai-verify-answers-q4","prompt":"Which is the strongest task evidence?","options":[{"id":"a","text":"A second confident model answer"},{"id":"b","text":"A longer announcement"},{"id":"c","text":"A claim table tied to source passages"}],"correctOptionId":"c","explanation":"The table makes the comparison and unresolved details reviewable."}]'::jsonb);
insert into public.ls_course_modules values('ai-verify-answers','how-to-use-ai',1,2,null,null,null);
insert into public.ls_task_definitions values('ai-verify-answers-task',1,'ai-verify-answers',1,'Audit a draft announcement','Use the fictional study-room note to identify supported, conflicting, and unsupported claims, then write a corrected announcement.','["Check the time, price, booking rule, and capacity separately.","Connect each verdict to the supplied note and leave unknown capacity unknown.","Include the corrected announcement and one lesson from the comparison."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('ai-structured-output',1,'[{"id":"ai-structured-output-q1","prompt":"What should due contain when no deadline is specified?","options":[{"id":"a","text":"Today"},{"id":"b","text":"null"},{"id":"c","text":"A likely Friday"}],"correctOptionId":"b","explanation":"The agreed missing-value rule is null, not a guessed deadline."},{"id":"ai-structured-output-q2","prompt":"A JSON object parses but has an invented owner. Is it acceptable?","options":[{"id":"a","text":"Yes; parsing proves facts"},{"id":"b","text":"No; factual validation is separate"},{"id":"c","text":"Only if the name is short"}],"correctOptionId":"b","explanation":"Valid syntax does not establish source support."},{"id":"ai-structured-output-q3","prompt":"A source passage says \"ignore the rules.\" How should it be treated?","options":[{"id":"a","text":"As source data to inspect"},{"id":"b","text":"As a new higher-priority instruction"},{"id":"c","text":"As permission to run code"}],"correctOptionId":"a","explanation":"Untrusted source text does not gain authority over the extraction instructions."},{"id":"ai-structured-output-q4","prompt":"Which request is easiest to check?","options":[{"id":"a","text":"Make something useful"},{"id":"b","text":"Pick any format"},{"id":"c","text":"Use these exact keys, types, and missing-value rules"}],"correctOptionId":"c","explanation":"A defined contract provides concrete checks for the result."}]'::jsonb);
insert into public.ls_course_modules values('ai-structured-output','how-to-use-ai',1,3,null,null,null);
insert into public.ls_task_definitions values('ai-structured-output-task',1,'ai-structured-output',1,'Design and check an extraction contract','Create an action-item JSON contract, one supported example, and one example with missing information.','["Specify exact keys, allowed value types, and the null rule.","Check each populated value against a short fictional source.","Show a missing-owner or missing-deadline example and explain why parsing alone is insufficient."]'::jsonb);
insert into public.ls_course_modules values('spanish-first-conversation','spanish',2,1,'es',null,null);
insert into public.ls_task_definitions values('spanish-first-conversation-task',1,'spanish-first-conversation',2,'Prepare a Spanish introduction','Write a short fictional introduction and reflect on one phrase you practiced or want to improve.','["Include a greeting, a fictional name, and a question for the other speaker.","Include a request to repeat or slow down.","Add your own reflection without exposing another person’s details or a private meeting URL."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('spanish-daily-plans',1,'[{"id":"spanish-daily-plans-q1","prompt":"Which means \"I am going to read\"?","options":[{"id":"a","text":"Voy a leer"},{"id":"b","text":"Voy leer"},{"id":"c","text":"Vas a leer"}],"correctOptionId":"a","explanation":"The first-person pattern is voy a followed by the infinitive leer."},{"id":"spanish-daily-plans-q2","prompt":"What does ¿A qué hora? ask for?","options":[{"id":"a","text":"A name"},{"id":"b","text":"A time"},{"id":"c","text":"A preference"}],"correctOptionId":"b","explanation":"Hora refers to the time of the activity."},{"id":"spanish-daily-plans-q3","prompt":"Which word means tomorrow?","options":[{"id":"a","text":"Hoy"},{"id":"b","text":"Ahora"},{"id":"c","text":"Mañana"}],"correctOptionId":"c","explanation":"Mañana means tomorrow in this planning phrase; hoy means today."},{"id":"spanish-daily-plans-q4","prompt":"Two online partners agree to six. What still needs clarification?","options":[{"id":"a","text":"Nothing; six is universal"},{"id":"b","text":"The date, time zone, and morning/evening context"},{"id":"c","text":"Their private home addresses"}],"correctOptionId":"b","explanation":"A clock time alone may refer to different instants in different places."}]'::jsonb);
insert into public.ls_course_modules values('spanish-daily-plans','spanish',1,2,'es',null,null);
insert into public.ls_task_definitions values('spanish-daily-plans-task',1,'spanish-daily-plans',1,'Write and confirm a Spanish plan','Create a fictional short exchange that proposes an activity, changes a time, and confirms the final plan.','["Use voy a plus an infinitive and ask ¿A qué hora? or an equivalent question.","Show the changed time and a clear final confirmation.","Add one phrase you needed to repeat or improve; keep real scheduling details private."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('spanish-preferences',1,'[{"id":"spanish-preferences-q1","prompt":"Which fits \"I like books\"?","options":[{"id":"a","text":"Me gusta los libros"},{"id":"b","text":"Me gustan los libros"},{"id":"c","text":"Me gustan leer"}],"correctOptionId":"b","explanation":"Los libros is plural, so this pattern uses gustan."},{"id":"spanish-preferences-q2","prompt":"Which fits an activity?","options":[{"id":"a","text":"Me gusta caminar"},{"id":"b","text":"Me gustan caminar"},{"id":"c","text":"Me gusto caminar"}],"correctOptionId":"a","explanation":"An infinitive activity uses me gusta in this pattern."},{"id":"spanish-preferences-q3","prompt":"What does ¿Prefieres leer o caminar? ask?","options":[{"id":"a","text":"What time it is"},{"id":"b","text":"What your name is"},{"id":"c","text":"Which activity you prefer"}],"correctOptionId":"c","explanation":"Prefieres offers a choice between reading and walking."},{"id":"spanish-preferences-q4","prompt":"If you prefer another activity, what is useful?","options":[{"id":"a","text":"Pretend to agree"},{"id":"b","text":"State your preference politely and propose an alternative"},{"id":"c","text":"Stop listening"}],"correctOptionId":"b","explanation":"A clear alternative lets both speakers negotiate an activity."}]'::jsonb);
insert into public.ls_course_modules values('spanish-preferences','spanish',1,3,'es',null,null);
insert into public.ls_task_definitions values('spanish-preferences-task',1,'spanish-preferences',1,'Find a shared activity in Spanish','Write a fictional dialogue that compares two preferences and reaches a mutually acceptable activity.','["Include one correct gusta sentence and one correct gustan sentence.","Ask a preference question and respond with a real choice within the fictional scenario.","Explain one language correction and show the agreed activity."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('python-clean-labels',1,'[{"id":"python-clean-labels-q1","prompt":"What is \"  Deep Work  \".strip().lower()?","options":[{"id":"a","text":"\"deepwork\""},{"id":"b","text":"\"deep work\""},{"id":"c","text":"\"  deep work  \""}],"correctOptionId":"b","explanation":"strip removes only edge whitespace; lower changes case."},{"id":"python-clean-labels-q2","prompt":"When should the empty check happen?","options":[{"id":"a","text":"After stripping"},{"id":"b","text":"Only before stripping"},{"id":"c","text":"Only after sorting"}],"correctOptionId":"a","explanation":"Whitespace-only strings become empty after stripping."},{"id":"python-clean-labels-q3","prompt":"What happens to two labels that both become \"study\"?","options":[{"id":"a","text":"Keep both"},{"id":"b","text":"Keep neither"},{"id":"c","text":"Keep exactly one"}],"correctOptionId":"a","explanation":"This contract preserves repeated records."},{"id":"python-clean-labels-q4","prompt":"Which action breaks the exercise contract?","options":[{"id":"a","text":"Creating a new list"},{"id":"b","text":"Calling lower()"},{"id":"c","text":"Replacing items in the input list"}],"correctOptionId":"c","explanation":"The caller must retain its original input."}]'::jsonb);
insert into public.ls_python_exercise_versions values('python-normalize-labels',1,'["case-1","case-2","case-3","case-4","case-5","case-6"]'::jsonb);
insert into public.ls_course_modules values('python-clean-labels','python-automation',1,1,null,'python-normalize-labels',1);
insert into public.ls_task_definitions values('python-clean-labels-task',1,'python-clean-labels',1,'Clean a messy label batch','Implement the cleaner and explain one case where the order of transformations changes the result.','["Show mixed case, surrounding whitespace, and a whitespace-only label.","Keep duplicates and internal spaces in your example.","Describe the output and how you checked input preservation."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('python-group-records',1,'[{"id":"python-group-records-q1","prompt":"Why use totals.get(category, 0)?","options":[{"id":"a","text":"To remove the category"},{"id":"b","text":"To supply zero for a new category"},{"id":"c","text":"To sort records"}],"correctOptionId":"b","explanation":"A new bucket starts at zero; existing buckets retain their accumulated value."},{"id":"python-group-records-q2","prompt":"Records read=3, walk=5, read=4 produce what read total?","options":[{"id":"a","text":"4"},{"id":"b","text":"3"},{"id":"c","text":"7"}],"correctOptionId":"c","explanation":"Both read records contribute, even when separated."},{"id":"python-group-records-q3","prompt":"What happens to a single zero-minute category?","options":[{"id":"a","text":"It remains with total 0"},{"id":"b","text":"It is always removed"},{"id":"c","text":"Its total becomes 1"}],"correctOptionId":"a","explanation":"Presence and positive duration are separate facts."},{"id":"python-group-records-q4","prompt":"Are Read and read combined here?","options":[{"id":"a","text":"Yes, always"},{"id":"b","text":"No, keys remain exact"},{"id":"c","text":"Only if adjacent"}],"correctOptionId":"b","explanation":"Normalization is deliberately outside this grouping contract."}]'::jsonb);
insert into public.ls_python_exercise_versions values('python-group-minutes',1,'["case-1","case-2","case-3","case-4","case-5","case-6"]'::jsonb);
insert into public.ls_course_modules values('python-group-records','python-automation',1,2,null,'python-group-minutes',1);
insert into public.ls_task_definitions values('python-group-records-task',1,'python-group-records',1,'Build a category total','Aggregate a small fictional activity log and explain how repeated categories are combined.','["Show at least two categories and one repeated category separated by another row.","Include a zero-minute record and show that its category remains present.","Explain accumulation versus overwriting and confirm nested inputs stay unchanged."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('python-build-report',1,'[{"id":"python-build-report-q1","prompt":"Why sort the keys?","options":[{"id":"a","text":"To change totals"},{"id":"b","text":"To produce consistent line order"},{"id":"c","text":"To remove zero totals"}],"correctOptionId":"b","explanation":"Sorting makes output order independent of dictionary insertion order."},{"id":"python-build-report-q2","prompt":"What is the required line for read with total 0?","options":[{"id":"a","text":"\"read: 0\""},{"id":"b","text":"\"read: \""},{"id":"c","text":"No line"}],"correctOptionId":"a","explanation":"Zero totals are retained and formatted as integers."},{"id":"python-build-report-q3","prompt":"What must the function return?","options":[{"id":"a","text":"One printed message"},{"id":"b","text":"A list of formatted strings"},{"id":"c","text":"The original dictionary"}],"correctOptionId":"b","explanation":"The caller needs a returned list, not only console output."},{"id":"python-build-report-q4","prompt":"Does sorted(totals) modify totals?","options":[{"id":"a","text":"Yes, it deletes values"},{"id":"b","text":"Yes, it sorts the dictionary in place"},{"id":"c","text":"No, it returns a new list of keys"}],"correctOptionId":"c","explanation":"sorted creates a new list; the input dictionary remains intact."}]'::jsonb);
insert into public.ls_python_exercise_versions values('python-report-lines',1,'["case-1","case-2","case-3","case-4","case-5","case-6"]'::jsonb);
insert into public.ls_course_modules values('python-build-report','python-automation',1,3,null,'python-report-lines',1);
insert into public.ls_task_definitions values('python-build-report-task',1,'python-build-report',1,'Publish a reproducible report summary','Build the report function and describe why the same totals produce the same output order.','["Show the exact list of lines for an input entered in reverse alphabetical order.","Include a zero total and an empty-input result.","Explain return versus print and confirm you preserved the input."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('ai-work-email',1,'[{"id":"ai-work-email-q1","prompt":"Friday is only proposed. Which sentence preserves that?","options":[{"id":"a","text":"Thanks for agreeing to Friday"},{"id":"b","text":"Could you share feedback by Friday?"},{"id":"c","text":"Your Friday deadline is confirmed"}],"correctOptionId":"b","explanation":"A question asks for agreement without claiming it already exists."},{"id":"ai-work-email-q2","prompt":"What should the prompt include?","options":[{"id":"a","text":"Only \"write an email\""},{"id":"b","text":"A made-up discount"},{"id":"c","text":"Audience, facts, goal, and constraints"}],"correctOptionId":"c","explanation":"These details help the draft match the actual communication task."},{"id":"ai-work-email-q3","prompt":"The draft says \"attached\" but no file is attached. What should happen?","options":[{"id":"a","text":"Review and correct it before sending"},{"id":"b","text":"Send because the model wrote it"},{"id":"c","text":"Ignore it if the tone is friendly"}],"correctOptionId":"a","explanation":"Attachment claims must match the actual message."},{"id":"ai-work-email-q4","prompt":"What does completing this lesson authorize?","options":[{"id":"a","text":"Automatic sending to customers"},{"id":"b","text":"Producing and reviewing a fictional draft"},{"id":"c","text":"Uploading confidential inboxes"}],"correctOptionId":"b","explanation":"The exercise neither sends messages nor authorizes disclosure of real confidential data."}]'::jsonb);
insert into public.ls_course_modules values('ai-work-email','ai-for-work',1,1,null,null,null);
insert into public.ls_task_definitions values('ai-work-email-task',1,'ai-work-email',1,'Review a feedback-request email','Prepare a prompt and a fictional email asking Morgan for slide feedback; document your review before sending would occur.','["Include a subject, one clear request, and Friday as a proposal.","Show two fact checks and one revision that avoids an invented commitment.","Use fictional information and label the message as a draft."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('ai-work-meeting-actions',1,'[{"id":"ai-work-meeting-actions-q1","prompt":"Ari suggested a logo, but the team kept the old one. What is the decision?","options":[{"id":"a","text":"Create the suggested logo"},{"id":"b","text":"Keep the current logo for the demo"},{"id":"c","text":"Assign Ari to redesign it"}],"correctOptionId":"b","explanation":"The explicit agreement takes precedence over the earlier suggestion."},{"id":"ai-work-meeting-actions-q2","prompt":"No owner was chosen for mobile testing. What belongs in owner?","options":[{"id":"a","text":"A guessed participant"},{"id":"b","text":"The first speaker"},{"id":"c","text":"null or an explicitly unknown marker"}],"correctOptionId":"c","explanation":"The summary must preserve the unresolved assignment."},{"id":"ai-work-meeting-actions-q3","prompt":"Why include an evidence phrase?","options":[{"id":"a","text":"To make extraction reviewable"},{"id":"b","text":"To prove every suggestion was approved"},{"id":"c","text":"To avoid reading the notes"}],"correctOptionId":"a","explanation":"A source phrase lets a reviewer check each classification and field."},{"id":"ai-work-meeting-actions-q4","prompt":"Does the meeting date automatically become each task deadline?","options":[{"id":"a","text":"Yes"},{"id":"b","text":"No"},{"id":"c","text":"Only for short meetings"}],"correctOptionId":"b","explanation":"A deadline needs its own support in the notes."}]'::jsonb);
insert into public.ls_course_modules values('ai-work-meeting-actions','ai-for-work',1,2,null,null,null);
insert into public.ls_task_definitions values('ai-work-meeting-actions-task',1,'ai-work-meeting-actions',1,'Extract decisions and open actions','Turn the fictional logo/demo notes into a reviewable meeting summary without assigning missing owners.','["Separate the rejected/proposed logo idea from the actual decision.","Include Bo’s explicit action and date, and keep mobile ownership unresolved.","Attach evidence phrases and explain one classification you checked."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('ai-work-review-workflow',1,'[{"id":"ai-work-review-workflow-q1","prompt":"Which is the most concrete factual review check?","options":[{"id":"a","text":"The draft feels polished"},{"id":"b","text":"Every claim is supported by the brief"},{"id":"c","text":"The draft is longer"}],"correctOptionId":"b","explanation":"Source support can be checked claim by claim."},{"id":"ai-work-review-workflow-q2","prompt":"A missing-data test omits the time. What should a draft do?","options":[{"id":"a","text":"Reuse a previous time"},{"id":"b","text":"Invent the most convenient time"},{"id":"c","text":"Keep the time unknown or request clarification"}],"correctOptionId":"c","explanation":"A previous example does not establish a fact for this one."},{"id":"ai-work-review-workflow-q3","prompt":"A draft passes formatting but invents a link. What next?","options":[{"id":"a","text":"Correct and recheck the unsupported claim"},{"id":"b","text":"Publish because most checks passed"},{"id":"c","text":"Ignore facts if the tone is friendly"}],"correctOptionId":"a","explanation":"A factual failure is not cancelled out by good formatting."},{"id":"ai-work-review-workflow-q4","prompt":"What does a 3/4 checklist result mean here?","options":[{"id":"a","text":"The model is 75% accurate everywhere"},{"id":"b","text":"Three listed checks passed for this draft"},{"id":"c","text":"The draft is automatically approved"}],"correctOptionId":"b","explanation":"This is a local review record, not a general performance estimate."}]'::jsonb);
insert into public.ls_course_modules values('ai-work-review-workflow','ai-for-work',1,3,null,null,null);
insert into public.ls_task_definitions values('ai-work-review-workflow-task',1,'ai-work-review-workflow',1,'Create a two-case review record','Review normal and missing-data announcements with explicit checks, then correct one deliberately unsupported detail.','["Include both supplied briefs and a four-check review table.","Show the unsupported detail, its correction, and a recheck.","State when a human must request clarification and who decides whether to publish."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('french-first-conversation',1,'[{"id":"french-first-conversation-q1","prompt":"Which phrase introduces your name?","options":[{"id":"a","text":"Je m’appelle Alex"},{"id":"b","text":"Au revoir"},{"id":"c","text":"Et vous ?"}],"correctOptionId":"a","explanation":"Je m’appelle introduces the name you use in the conversation."},{"id":"french-first-conversation-q2","prompt":"Which politely asks for repetition?","options":[{"id":"a","text":"Merci"},{"id":"b","text":"Bonjour"},{"id":"c","text":"Pouvez-vous répéter, s’il vous plaît ?"}],"correctOptionId":"c","explanation":"This asks the partner to repeat rather than pretending you understood."},{"id":"french-first-conversation-q3","prompt":"How is vous used in this lesson’s opening?","options":[{"id":"a","text":"Only for a close friend"},{"id":"b","text":"As polite address to a new partner"},{"id":"c","text":"Only to introduce yourself"}],"correctOptionId":"b","explanation":"Vous can politely address one person; it also has a plural use."},{"id":"french-first-conversation-q4","prompt":"Must you share your real full name to practice?","options":[{"id":"a","text":"Yes"},{"id":"b","text":"No; a fictional first name is enough"},{"id":"c","text":"Only if you make a mistake"}],"correctOptionId":"b","explanation":"The exercise works with fictional details and does not require private information."}]'::jsonb);
insert into public.ls_course_modules values('french-first-conversation','french',1,1,'fr',null,null);
insert into public.ls_task_definitions values('french-first-conversation-task',1,'french-first-conversation',1,'Write your first French exchange','Create a fictional six-line opening and describe one phrase you practiced or improved.','["Include a greeting, name introduction, and return question.","Use a polite repetition request and a goodbye.","Keep address consistent and add a short reflection without private partner details."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('french-daily-plans',1,'[{"id":"french-daily-plans-q1","prompt":"Which means \"I am going to read\"?","options":[{"id":"a","text":"Je vais à lire"},{"id":"b","text":"Je vais lire"},{"id":"c","text":"Je lire vais"}],"correctOptionId":"b","explanation":"The future pattern is the appropriate form of aller followed directly by an infinitive."},{"id":"french-daily-plans-q2","prompt":"What does demain mean?","options":[{"id":"a","text":"Tomorrow"},{"id":"b","text":"Yesterday"},{"id":"c","text":"A clock"}],"correctOptionId":"a","explanation":"Demain places the plan tomorrow."},{"id":"french-daily-plans-q3","prompt":"What does À quelle heure ? ask?","options":[{"id":"a","text":"Which name?"},{"id":"b","text":"Which hobby?"},{"id":"c","text":"At what time?"}],"correctOptionId":"c","explanation":"This question asks for the activity’s time."},{"id":"french-daily-plans-q4","prompt":"What should follow a changed proposed time?","options":[{"id":"a","text":"A clear confirmation of the new time"},{"id":"b","text":"An invented meeting link"},{"id":"c","text":"Silence because the old time is still certain"}],"correctOptionId":"a","explanation":"Repeating the updated plan helps both people confirm the same details."}]'::jsonb);
insert into public.ls_course_modules values('french-daily-plans','french',1,2,'fr',null,null);
insert into public.ls_task_definitions values('french-daily-plans-task',1,'french-daily-plans',1,'Confirm a French plan','Write a fictional exchange about tomorrow, including a changed time and the final confirmation.','["Use je vais plus an infinitive and ask about a time.","Show the change from one proposed time to another.","Explain the infinitive pattern and keep any real appointment details private."]'::jsonb);
insert into public.ls_content_versions(module_id,content_version,quiz) values('french-preferences',1,'[{"id":"french-preferences-q1","prompt":"Which expresses a preference for walking?","options":[{"id":"a","text":"Je préfère marcher"},{"id":"b","text":"Je m’appelle marcher"},{"id":"c","text":"À quelle heure ?"}],"correctOptionId":"a","explanation":"Je préfère introduces the preferred activity."},{"id":"french-preferences-q2","prompt":"Which is the written negative pattern taught here?","options":[{"id":"a","text":"Je pas aime courir"},{"id":"b","text":"Je n’aime pas courir"},{"id":"c","text":"Je n’aime courir pas"}],"correctOptionId":"b","explanation":"The written pattern places n’ before aime and pas after it."},{"id":"french-preferences-q3","prompt":"What does ou do in lire ou marcher?","options":[{"id":"a","text":"Marks yesterday"},{"id":"b","text":"Means and"},{"id":"c","text":"Offers the alternative \"or\""}],"correctOptionId":"c","explanation":"The question offers a choice between two activities."},{"id":"french-preferences-q4","prompt":"If your preferences differ, what supports conversation?","options":[{"id":"a","text":"Ignore the answer"},{"id":"b","text":"Offer another activity and listen"},{"id":"c","text":"Claim the other person is wrong"}],"correctOptionId":"b","explanation":"A respectful alternative keeps both speakers involved in choosing."}]'::jsonb);
insert into public.ls_course_modules values('french-preferences','french',1,3,'fr',null,null);
insert into public.ls_task_definitions values('french-preferences-task',1,'french-preferences',1,'Compare preferences in French','Write a fictional dialogue where two people compare activities and agree on one.','["Include a like, a dislike, and a preference phrase.","Ask an either-or question and show a response to a different first choice.","State the agreed activity and explain one language improvement."]'::jsonb);
