do $$ begin if (select quiz from public.ls_content_versions where module_id='python-first-function' and content_version=1) is distinct from '[{"id":"python-return","prompt":"What does return total do inside a function?","options":[{"id":"a","text":"Only displays total in the console"},{"id":"b","text":"Gives total back to the caller and ends this function call"},{"id":"c","text":"Repeats the loop"}],"correctOptionId":"b","explanation":"return sends the value to the caller and ends this call. print displays a value but does not replace returning it."},{"id":"python-mixed","prompt":"What should count_completed([True, False, True]) return?","options":[{"id":"a","text":"3"},{"id":"b","text":"True"},{"id":"c","text":"2"}],"correctOptionId":"c","explanation":"Two entries are True. Count completed habits, not every entry in the list."},{"id":"python-empty","prompt":"No habits have been entered: count_completed([]). What is the expected count?","options":[{"id":"a","text":"0"},{"id":"b","text":"1"},{"id":"c","text":"The text ''empty''"}],"correctOptionId":"a","explanation":"With no entries, the loop has nothing to count. The starting count of zero is also the result."},{"id":"python-return-position","prompt":"Why should the result be returned after the loop in this exercise?","options":[{"id":"a","text":"A return inside the loop always creates a syntax error"},{"id":"b","text":"Returning on the first iteration would skip the remaining items"},{"id":"c","text":"Python cannot return numbers inside a loop"}],"correctOptionId":"b","explanation":"return ends the function immediately. Place it after the loop so all entries can contribute to the result."}]'::jsonb then raise exception 'Published quiz snapshot differs: python-first-function';end if;end $$;
do $$ begin if (select quiz from public.ls_content_versions where module_id='ai-clear-requests' and content_version=1) is distinct from '[{"id":"ai-request","prompt":"Which request gives an assistant the clearest task?","options":[{"id":"a","text":"Write something great."},{"id":"b","text":"Using the three supplied agenda items, draft a friendly meeting reminder under 80 words. Do not invent a time or location."},{"id":"c","text":"Be clever about meetings."}],"correctOptionId":"b","explanation":"This request supplies a task, context, tone, length and a boundary against inventing details. Clear instructions help you evaluate the result; they do not guarantee correctness."},{"id":"ai-unsupported","prompt":"Your notes say Tuesday, but the generated reminder adds 10:00. What should you do?","options":[{"id":"a","text":"Assume the assistant looked up the calendar"},{"id":"b","text":"Accept it because the wording sounds confident"},{"id":"c","text":"Remove or flag the time and verify it with the organizer"}],"correctOptionId":"c","explanation":"The supplied notes do not establish a time. A plausible addition is still unsupported; verify it before sending the reminder."},{"id":"ai-sensitive","prompt":"You want help improving a customer reply. What is the best starting input for this exercise?","options":[{"id":"a","text":"An invented or redacted example containing only the details needed for the task"},{"id":"b","text":"A complete customer database"},{"id":"c","text":"Your account password so the assistant can read everything"}],"correctOptionId":"a","explanation":"An invented or redacted example can preserve the writing problem without exposing unnecessary personal data or credentials."},{"id":"ai-source","prompt":"An answer includes a source link. Does that alone verify its claim?","options":[{"id":"a","text":"Yes, any link is enough"},{"id":"b","text":"No; open the original source and check that it supports the claim and is relevant"},{"id":"c","text":"Yes, if the answer is long"}],"correctOptionId":"b","explanation":"A citation is a lead to check. Confirm the source exists, says what is claimed, and fits the date and context of your question."}]'::jsonb then raise exception 'Published quiz snapshot differs: ai-clear-requests';end if;end $$;
do $$ begin if (select quiz from public.ls_content_versions where module_id='spanish-first-conversation' and content_version=2) is distinct from '[{"id":"spanish-name","prompt":"Which phrase means ''My name is Sam''?","options":[{"id":"a","text":"Me llamo Sam."},{"id":"b","text":"¿Cómo te llamas?"},{"id":"c","text":"Hasta luego."}],"correctOptionId":"a","explanation":"Me llamo introduces your name. ¿Cómo te llamas? asks the other person''s name; Hasta luego is a farewell."},{"id":"spanish-question","prompt":"How do you ask someone''s name informally?","options":[{"id":"a","text":"Gracias."},{"id":"b","text":"Soy de Canadá."},{"id":"c","text":"¿Cómo te llamas?"}],"correctOptionId":"c","explanation":"¿Cómo te llamas? asks ''What is your name?'' in an informal conversation. Gracias means ''Thank you''."},{"id":"spanish-repeat","prompt":"You did not catch what your partner said. Which phrase asks them to repeat it?","options":[{"id":"a","text":"Hola."},{"id":"b","text":"¿Puedes repetir, por favor?"},{"id":"c","text":"Me gusta cocinar."}],"correctOptionId":"b","explanation":"¿Puedes repetir, por favor? means ''Can you repeat, please?'' It lets you keep participating when you miss a phrase."},{"id":"spanish-origin","prompt":"Someone asks ''¿De dónde eres?'' Which answer fits?","options":[{"id":"a","text":"Soy de Canadá."},{"id":"b","text":"Más despacio, por favor."},{"id":"c","text":"Hasta luego."}],"correctOptionId":"a","explanation":"¿De dónde eres? asks where you are from. Soy de Canadá answers ''I am from Canada''. You can use a fictional place for practice."}]'::jsonb then raise exception 'Published quiz snapshot differs: spanish-first-conversation';end if;end $$;
